test_adds.cpp代码如下：
`
#include "test_adds.h"

int main(int argc, char **argv)
{
    int fuzzCount = 1;
    printf("start ---- asStridedFuzz\n");
    // 设置报告路径
    DT_Set_Report_Path((char *)"./");
    // 设置使能fork模式，每个测试用例单独在子进程运行
    DT_SetEnableFork(1);
    // 检测大内存使用，超过2048M使用或者1024M分配则当做bug报错
    DT_SetCheckOutOfMemory(1024, 2048);
    // 是能内存泄漏单次执行检测，默认也开启
    DT_Enable_Leak_Check(1, 0);
    // 设置用例单次执行多久超时，4.9版本后已经默认开启，默认600s
    DT_Set_TimeOut_Second(600);
    // 公司目前要求单测试用例最低运行3千万次
    DT_FUZZ_START(0, fuzzCount, "asStridedFuzz", 0)
    {
        int m = *(s32 *)DT_SetGetNumberRange(&g_Element[0], 64, 2, 32);
        int n = *(s32 *)DT_SetGetNumberRange(&g_Element[1], 26, 2, 32);
        int k = *(s32 *)DT_SetGetNumberRange(&g_Element[2], 128, 2, 256);
        int l = *(s32 *)DT_SetGetNumberRange(&g_Element[3], 2, 2, 2);
        test_adds(m, n, k, l);
    }
    DT_FUZZ_END()
    // 使用fork模式，用例主要在子进程执行，主进程通过DT_GetIsPass获取用例执行是否发现bug
    if (DT_GetIsPass() == 0) {
        printf("asStridedFuzz is not ok\r\n");
    } else {
        printf("asStridedFuzz is ok\r\n");
    }
    printf("end ---- asStridedFuzz\n");
}
`

